package app.slipnet.data.export

import app.slipnet.domain.model.ServerProfile
import app.slipnet.util.BundleCrypto
import org.json.JSONObject
import org.junit.Assert.*
import org.junit.Test

/** Frozen synthetic wire samples; these are never regenerated by the exporter under test. */
class ImportCorpusTest {
    @Test fun soarImportsKeepEveryExplicitTcpPolicyDespiteNewEditorDefaults() {
        for (type in listOf(app.slipnet.domain.model.TunnelType.SOAR, app.slipnet.domain.model.TunnelType.SOAR_SSH)) {
            for (mode in app.slipnet.domain.model.SoarConfig.TCP_MODES) {
                val original = ServerProfile(name = "Synthetic Soar policy", domain = "dns.example.invalid",
                    resolvers = listOf(app.slipnet.domain.model.DnsResolver("192.0.2.53")),
                    tunnelType = type, dnsttPublicKey = "11".repeat(32),
                    sshUsername = "fixture-user", sshPassword = "fixture-password", soarTcpMode = mode)
                val restored = success(ConfigExporter().exportSingleProfile(original)).profiles.single()
                assertEquals(type, restored.tunnelType)
                assertEquals(mode, restored.soarTcpMode)
            }
        }
    }

    private val importer = ConfigImporter()
    private val corpus = requireNotNull(javaClass.getResourceAsStream("/import-corpus/cases.json")) {
        "Missing import corpus resources"
    }.bufferedReader(Charsets.UTF_8).use { JSONObject(it.readText()).getJSONArray("cases") }
    private val device = "fixture-device-01"

    private fun cases(category: String): List<JSONObject> = (0 until corpus.length())
        .map { corpus.getJSONObject(it) }.filter { it.getString("category") == category }

    private fun success(input: String, password: String? = null): ImportResult.Success {
        val result = importer.parseAndImport(input, localDeviceId = device, bundlePassword = password)
        assertTrue(result.toString(), result is ImportResult.Success)
        return result as ImportResult.Success
    }

    private fun assertFields(expected: JSONObject, profile: ServerProfile) {
        assertEquals(expected.getString("name"), profile.name)
        assertEquals(expected.getString("domain"), profile.domain)
        assertEquals(expected.getString("tunnelType"), profile.tunnelType.name)
        assertEquals(expected.getInt("tcpListenPort"), profile.tcpListenPort)
        assertEquals(expected.getString("resolverHost"), profile.resolvers.single().host)
        if (expected.has("sshUsername")) assertEquals(expected.getString("sshUsername"), profile.sshUsername)
        if (expected.has("sshPassword")) assertEquals(expected.getString("sshPassword"), profile.sshPassword)
        if (expected.has("socksPassword")) assertEquals(expected.getString("socksPassword"), profile.socksPassword)
        if (expected.has("isLocked")) assertEquals(expected.getBoolean("isLocked"), profile.isLocked)
        if (expected.has("lockPasswordHash")) assertEquals(expected.getString("lockPasswordHash"), profile.lockPasswordHash)
        if (expected.has("expirationDate")) assertEquals(expected.getLong("expirationDate"), profile.expirationDate)
        if (expected.has("allowSharing")) assertEquals(expected.getBoolean("allowSharing"), profile.allowSharing)
        if (expected.has("boundDeviceId")) assertEquals(expected.getString("boundDeviceId"), profile.boundDeviceId)
        if (expected.has("resolversHidden")) assertEquals(expected.getBoolean("resolversHidden"), profile.resolversHidden)
        if (expected.has("collectionId")) assertEquals(expected.getString("collectionId"), profile.collectionId)
        if (expected.has("coreLink")) assertEquals(expected.getString("coreLink"), profile.coreLink)
    }

    @Test fun allKnownWireVersionsRemainReadable() {
        val known = cases("known")
        assertEquals((1..ConfigExporter.VERSION.toInt()).toList(), known.map { it.getInt("version") })
        for (sample in known) {
            val result = success(sample.getString("input"))
            assertTrue("v${sample.getInt("version")}: ${result.warnings}", result.warnings.isEmpty())
            assertFields(sample.getJSONObject("expected"), result.profiles.single())
        }
    }

    @Test fun securityFieldsArePreservedInSupportedSamples() {
        for (sample in cases("security")) {
            val result = success(sample.getString("input"))
            assertTrue(result.warnings.toString(), result.warnings.isEmpty())
            val profile = result.profiles.single()
            assertFields(sample.getJSONObject("expected"), profile)
            if (profile.resolversHidden) {
                assertEquals("192.0.2.54", profile.defaultResolvers.single().host)
            }
            assertThrows(IllegalStateException::class.java) { ConfigExporter().exportSingleProfile(profile) }
        }
    }

    @Test fun deviceBoundSamplesAreRejectedForAnotherDevice() {
        for (sample in cases("security")) {
            val result = importer.parseAndImport(sample.getString("input"), localDeviceId = "another-device")
            assertTrue(result.toString(), result is ImportResult.Error)
            assertTrue((result as ImportResult.Error).message.contains("bound to a different device"))
        }
    }

    @Test fun unknownVersionsAreExplicitlyRejectedBeforeSecurityFieldsCanBeDropped() {
        for (sample in cases("unknown")) {
            val result = importer.parseAndImport(sample.getString("input"), localDeviceId = device)
            assertTrue(sample.getString("id") + ": " + result, result is ImportResult.Error)
            assertTrue((result as ImportResult.Error).message.contains("Unsupported version"))
        }
    }

    @Test fun mixedInputKeepsSupportedRowsAndReportsEveryRejectedRow() {
        val known = cases("known").last()
        val unknown = cases("unknown").first()
        val result = success("[ss] user=old-account\n${unknown.getString("input")}\n" +
            "[ss] user=current-account\n${known.getString("input")}")
        assertEquals(1, result.profiles.size)
        assertFields(known.getJSONObject("expected"), result.profiles.single())
        assertEquals("current-account", result.profiles.single().importAccountHint)
        assertEquals(1, result.warnings.size)
        assertTrue(result.warnings.single().contains("Unsupported version"))
    }

    @Test fun passwordBundlesCannotBypassVersionOrDeviceChecks() {
        val unknown = cases("unknown").first().getString("input")
        val known = cases("known").last().getString("input")
        fun bundle(input: String) = ConfigExporter.BUNDLE_ENCRYPTED_SCHEME +
            WireBase64.encode(BundleCrypto.encrypt(input, "synthetic-bundle-password"))
        val unknownBundle = bundle(unknown)
        assertEquals(ImportResult.NeedsPassword, importer.parseAndImport(unknownBundle))
        val rejected = importer.parseAndImport(unknownBundle, bundlePassword = "synthetic-bundle-password")
        assertTrue(rejected.toString(), rejected is ImportResult.Error)
        assertTrue((rejected as ImportResult.Error).message.contains("Unsupported version"))
        val mixed = success(bundle("$known\n$unknown"), "synthetic-bundle-password")
        assertEquals(1, mixed.profiles.size)
        assertTrue(mixed.warnings.single().contains("Unsupported version"))
        val bound = bundle(cases("security").last().getString("input"))
        assertTrue(importer.parseAndImport(bound, localDeviceId = "other", bundlePassword = "synthetic-bundle-password")
            is ImportResult.Error)
    }

    @Test fun incompleteOrMalformedSecurityDataIsRejected() {
        for (sample in cases("malformed")) {
            val result = importer.parseAndImport(sample.getString("input"), localDeviceId = device)
            assertTrue(sample.getString("id") + ": " + result, result is ImportResult.Error)
            assertTrue((result as ImportResult.Error).message.contains(sample.getString("reason")))
        }
    }

    @Test fun currentExporterRetainsRestrictionsAndLosslessCredentials() {
        val original = ServerProfile(name = "Synthetic current profile", domain = "dns.example.invalid",
            resolvers = listOf(app.slipnet.domain.model.DnsResolver("192.0.2.53")),
            tunnelType = app.slipnet.domain.model.TunnelType.SLIPSTREAM,
            sshUsername = "user|نام", sshPassword = "not-real|пароль:🔒", socksUsername = "socks|user",
            socksPassword = "not-real|密码", boundDeviceId = device, expirationDate = 4_102_444_800_000L,
            allowSharing = false, collectionId = "synthetic-collection", collectionName = "سرور آزمایشی")
        val encoded = ConfigExporter().exportSingleProfile(original)
        val restored = success(encoded).profiles.single()
        assertEquals(original.sshUsername, restored.sshUsername)
        assertEquals(original.sshPassword, restored.sshPassword)
        assertEquals(original.socksUsername, restored.socksUsername)
        assertEquals(original.socksPassword, restored.socksPassword)
        assertEquals(original.boundDeviceId, restored.boundDeviceId)
        assertEquals(original.expirationDate, restored.expirationDate)
        assertFalse(restored.allowSharing)
        assertEquals(original.collectionId, restored.collectionId)
        assertEquals(original.collectionName, restored.collectionName)
    }
}
